    32  static int adjust_prog_btf_ext_info(const struct bpf_object *obj,
    33                                      const struct bpf_program *prog,
    34                                      const struct btf_ext_info *ext_info,
    35                                      void **prog_info, __u32 *prog_rec_cnt,
    36                                      __u32 *prog_rec_sz)
    37  {
    38          void *copy_start = NULL, *copy_end = NULL;
    39          void *rec, *rec_end, *new_prog_info;
    40          const struct btf_ext_info_sec *sec;
    41          size_t old_sz, new_sz;
    42          const char *sec_name;
    43          int i, off_adj;
    44
    45          for_each_btf_ext_sec(ext_info, sec) {
    46                  sec_name = btf__name_by_offset(obj->btf, sec->sec_name_off);
    47                  if (!sec_name)
    48                          return -EINVAL;
    49                  if (strcmp(sec_name, prog->sec_name) != 0)
    50                          continue;
    51
    52                  for_each_btf_ext_rec(ext_info, sec, i, rec) {
    53                          __u32 insn_off = *(__u32 *)rec / BPF_INSN_SZ;
    54
    55                          if (insn_off < prog->sec_insn_off)
    56                                  continue;
    57                          if (insn_off >= prog->sec_insn_off + prog->sec_insn_cnt)
    58                                  break;
    59
    60                          if (!copy_start)
    61                                  copy_start = rec;
    62                          copy_end = rec + ext_info->rec_size;
    63                  }
    64
    65                  if (!copy_start)
    66                          return -ENOENT;
    67
    68                  /* append func/line info of a given (sub-)program to the main
    69                   * program func/line info
    70                   */
    71                  old_sz = (size_t)(*prog_rec_cnt) * ext_info->rec_size;
    72                  new_sz = old_sz + (copy_end - copy_start);
    73                  new_prog_info = realloc(*prog_info, new_sz);
    74                  if (!new_prog_info)
    75                          return -ENOMEM;
    76                  *prog_info = new_prog_info;
    77                  *prog_rec_cnt = new_sz / ext_info->rec_size;
    78                  memcpy(new_prog_info + old_sz, copy_start, copy_end - copy_start);
    79
    80                  /* Kernel instruction offsets are in units of 8-byte
    81                   * instructions, while .BTF.ext instruction offsets generated
    82                   * by Clang are in units of bytes. So convert Clang offsets
    83                   * into kernel offsets and adjust offset according to program
    84                   * relocated position.
    85                   */
    86                  off_adj = prog->sub_insn_off - prog->sec_insn_off;
    87                  rec = new_prog_info + old_sz;
    88                  rec_end = new_prog_info + new_sz;
    89                  for (; rec < rec_end; rec += ext_info->rec_size) {
    90                          __u32 *insn_off = rec;
    91
    92                          *insn_off = *insn_off / BPF_INSN_SZ + off_adj;
    93                  }
    94                  *prog_rec_sz = ext_info->rec_size;
    95                  return 0;
    96          }
    97
    98          return -ENOENT;
    99  }
