   101  static int
   102  reloc_prog_func_and_line_info(const struct bpf_object *obj,
   103                                struct bpf_program *main_prog,
   104                                const struct bpf_program *prog)
   105  {
   106          int err;
   107
   108          /* no .BTF.ext relocation if .BTF.ext is missing or kernel doesn't
   109           * supprot func/line info
   110           */
   111          if (!obj->btf_ext || !kernel_supports(obj, FEAT_BTF_FUNC))
   112                  return 0;
   113
   114          /* only attempt func info relocation if main program's func_info
   115           * relocation was successful
   116           */
   117          if (main_prog != prog && !main_prog->func_info)
   118                  goto line_info;
   119
   120          err = adjust_prog_btf_ext_info(obj, prog, &obj->btf_ext->func_info,
   121                                         &main_prog->func_info,
   122                                         &main_prog->func_info_cnt,
   123                                         &main_prog->func_info_rec_size);
   124          if (err) {
   125                  if (err != -ENOENT) {
   126                          pr_warn("prog '%s': error relocating .BTF.ext function info: %d\n",
   127                                  prog->name, err);
   128                          return err;
   129                  }
   130                  if (main_prog->func_info) {
   131                          /*
   132                           * Some info has already been found but has problem
   133                           * in the last btf_ext reloc. Must have to error out.
   134                           */
   135                          pr_warn("prog '%s': missing .BTF.ext function info.\n", prog->name);
   136                          return err;
   137                  }
   138                  /* Have problem loading the very first info. Ignore the rest. */
   139                  pr_warn("prog '%s': missing .BTF.ext function info for the main program, skipping all of .BTF.ext func info.\n",
   140                          prog->name);
   141          }
   142
   143  line_info:
   144          /* don't relocate line info if main program's relocation failed */
   145          if (main_prog != prog && !main_prog->line_info)
   146                  return 0;
   147
   148          err = adjust_prog_btf_ext_info(obj, prog, &obj->btf_ext->line_info,
   149                                         &main_prog->line_info,
   150                                         &main_prog->line_info_cnt,
   151                                         &main_prog->line_info_rec_size);
   152          if (err) {
   153                  if (err != -ENOENT) {
   154                          pr_warn("prog '%s': error relocating .BTF.ext line info: %d\n",
   155                                  prog->name, err);
   156                          return err;
   157                  }
   158                  if (main_prog->line_info) {
   159                          /*
   160                           * Some info has already been found but has problem
   161                           * in the last btf_ext reloc. Must have to error out.
   162                           */
   163                          pr_warn("prog '%s': missing .BTF.ext line info.\n", prog->name);
   164                          return err;
   165                  }
   166                  /* Have problem loading the very first info. Ignore the rest. */
   167                  pr_warn("prog '%s': missing .BTF.ext line info for the main program, skipping all of .BTF.ext line info.\n",
   168                          prog->name);
   169          }
   170          return 0;
   171  }
