   213  static int
   214  bpf_object__reloc_code(struct bpf_object *obj, struct bpf_program *main_prog,
   215                         struct bpf_program *prog)
   216  {
   217          size_t sub_insn_idx, insn_idx, new_cnt;
   218          struct bpf_program *subprog;
   219          struct bpf_insn *insns, *insn;
   220          struct reloc_desc *relo;
   221          int err;
   222
   223          err = reloc_prog_func_and_line_info(obj, main_prog, prog);
   224          if (err)
   225                  return err;
   226
   227          for (insn_idx = 0; insn_idx < prog->sec_insn_cnt; insn_idx++) {
   228                  insn = &main_prog->insns[prog->sub_insn_off + insn_idx];
   229                  if (!insn_is_subprog_call(insn) && !insn_is_pseudo_func(insn))
   230                          continue;
   231
   232                  relo = find_prog_insn_relo(prog, insn_idx);
   233                  if (relo && relo->type == RELO_EXTERN_FUNC)
   234                          /* kfunc relocations will be handled later
   235                           * in bpf_object__relocate_data()
   236                           */
   237                          continue;
   238                  if (relo && relo->type != RELO_CALL && relo->type != RELO_SUBPROG_ADDR) {
   239                          pr_warn("prog '%s': unexpected relo for insn #%zu, type %d\n",
   240                                  prog->name, insn_idx, relo->type);
   241                          return -LIBBPF_ERRNO__RELOC;
   242                  }
   243                  if (relo) {
   244                          /* sub-program instruction index is a combination of
   245                           * an offset of a symbol pointed to by relocation and
   246                           * call instruction's imm field; for global functions,
   247                           * call always has imm = -1, but for static functions
   248                           * relocation is against STT_SECTION and insn->imm
   249                           * points to a start of a static function
   250                           *
   251                           * for subprog addr relocation, the relo->sym_off + insn->imm is
   252                           * the byte offset in the corresponding section.
   253                           */
   254                          if (relo->type == RELO_CALL)
   255                                  sub_insn_idx = relo->sym_off / BPF_INSN_SZ + insn->imm + 1;
   256                          else
   257                                  sub_insn_idx = (relo->sym_off + insn->imm) / BPF_INSN_SZ;
   258                  } else if (insn_is_pseudo_func(insn)) {
   259                          /*
   260                           * RELO_SUBPROG_ADDR relo is always emitted even if both
   261                           * functions are in the same section, so it shouldn't reach here.
   262                           */
   263                          pr_warn("prog '%s': missing subprog addr relo for insn #%zu\n",
   264                                  prog->name, insn_idx);
   265                          return -LIBBPF_ERRNO__RELOC;
   266                  } else {
   267                          /* if subprogram call is to a static function within
   268                           * the same ELF section, there won't be any relocation
   269                           * emitted, but it also means there is no additional
   270                           * offset necessary, insns->imm is relative to
   271                           * instruction's original position within the section
   272                           */
   273                          sub_insn_idx = prog->sec_insn_off + insn_idx + insn->imm + 1;
   274                  }
   275
   276                  /* we enforce that sub-programs should be in .text section */
   277                  subprog = find_prog_by_sec_insn(obj, obj->efile.text_shndx, sub_insn_idx);
   278                  if (!subprog) {
   279                          pr_warn("prog '%s': no .text section found yet sub-program call exists\n",
   280                                  prog->name);
   281                          return -LIBBPF_ERRNO__RELOC;
   282                  }
   283
   284                  /* if it's the first call instruction calling into this
   285                   * subprogram (meaning this subprog hasn't been processed
   286                   * yet) within the context of current main program:
   287                   *   - append it at the end of main program's instructions blog;
   288                   *   - process is recursively, while current program is put on hold;
   289                   *   - if that subprogram calls some other not yet processes
   290                   *   subprogram, same thing will happen recursively until
   291                   *   there are no more unprocesses subprograms left to append
   292                   *   and relocate.
   293                   */
   294                  if (subprog->sub_insn_off == 0) {
   295                          subprog->sub_insn_off = main_prog->insns_cnt;
   296
   297                          new_cnt = main_prog->insns_cnt + subprog->insns_cnt;
   298                          insns = libbpf_reallocarray(main_prog->insns, new_cnt, sizeof(*insns));
   299                          if (!insns) {
   300                                  pr_warn("prog '%s': failed to realloc prog code\n", main_prog->name);
   301                                  return -ENOMEM;
   302                          }
   303                          main_prog->insns = insns;
   304                          main_prog->insns_cnt = new_cnt;
   305
   306                          memcpy(main_prog->insns + subprog->sub_insn_off, subprog->insns,
   307                                 subprog->insns_cnt * sizeof(*insns));
   308
   309                          pr_debug("prog '%s': added %zu insns from sub-prog '%s'\n",
   310                                   main_prog->name, subprog->insns_cnt, subprog->name);
   311
   312                          /* The subprog insns are now appended. Append its relos too. */
   313                          err = append_subprog_relos(main_prog, subprog);
   314                          if (err)
   315                                  return err;
   316                          err = bpf_object__reloc_code(obj, main_prog, subprog);
   317                          if (err)
   318                                  return err;
   319                  }
   320
   321                  /* main_prog->insns memory could have been re-allocated, so
   322                   * calculate pointer again
   323                   */
   324                  insn = &main_prog->insns[prog->sub_insn_off + insn_idx];
   325                  /* calculate correct instruction position within current main
   326                   * prog; each main prog can have a different set of
   327                   * subprograms appended (potentially in different order as
   328                   * well), so position of any subprog can be different for
   329                   * different main programs */
   330                  insn->imm = subprog->sub_insn_off - (prog->sub_insn_off + insn_idx) - 1;
   331
   332                  pr_debug("prog '%s': insn #%zu relocated, imm %d points to subprog '%s' (now at %zu offset)\n",
   333                           prog->name, insn_idx, insn->imm, subprog->name, subprog->sub_insn_off);
   334          }
   335
   336          return 0;
   337  }
