   459  static int
   460  bpf_object__relocate(struct bpf_object *obj, const char *targ_btf_path)
   461  {
   462          struct bpf_program *prog;
   463          size_t i, j;
   464          int err;
   465
   466          if (obj->btf_ext) {
   467                  err = bpf_object__relocate_core(obj, targ_btf_path);
   468                  if (err) {
   469                          pr_warn("failed to perform CO-RE relocations: %d\n",
   470                                  err);
   471                          return err;
   472                  }
   473          }
   474
   475          /* Before relocating calls pre-process relocations and mark
   476           * few ld_imm64 instructions that points to subprogs.
   477           * Otherwise bpf_object__reloc_code() later would have to consider
   478           * all ld_imm64 insns as relocation candidates. That would
   479           * reduce relocation speed, since amount of find_prog_insn_relo()
   480           * would increase and most of them will fail to find a relo.
   481           */
   482          for (i = 0; i < obj->nr_programs; i++) {
   483                  prog = &obj->programs[i];
   484                  for (j = 0; j < prog->nr_reloc; j++) {
   485                          struct reloc_desc *relo = &prog->reloc_desc[j];
   486                          struct bpf_insn *insn = &prog->insns[relo->insn_idx];
   487
   488                          /* mark the insn, so it's recognized by insn_is_pseudo_func() */
   489                          if (relo->type == RELO_SUBPROG_ADDR)
   490                                  insn[0].src_reg = BPF_PSEUDO_FUNC;
   491                  }
   492          }
   493
   494          /* relocate subprogram calls and append used subprograms to main
   495           * programs; each copy of subprogram code needs to be relocated
   496           * differently for each main program, because its code location might
   497           * have changed.
   498           * Append subprog relos to main programs to allow data relos to be
   499           * processed after text is completely relocated.
   500           */
   501          for (i = 0; i < obj->nr_programs; i++) {
   502                  prog = &obj->programs[i];
   503                  /* sub-program's sub-calls are relocated within the context of
   504                   * its main program only
   505                   */
   506                  if (prog_is_subprog(obj, prog))

1                  if (prog_is_subprog(obj, prog))
     2                          continue;
     3
     4                  err = bpf_object__relocate_calls(obj, prog);
     5                  if (err) {
     6                          pr_warn("prog '%s': failed to relocate calls: %d\n",
     7                                  prog->name, err);
     8                          return err;
     9                  }
    10          }
    11          /* Process data relos for main programs */
    12          for (i = 0; i < obj->nr_programs; i++) {
    13                  prog = &obj->programs[i];
    14                  if (prog_is_subprog(obj, prog))
    15                          continue;
    16                  err = bpf_object__relocate_data(obj, prog);
    17                  if (err) {
    18                          pr_warn("prog '%s': failed to relocate data references: %d\n",
    19                                  prog->name, err);
    20                          return err;
    21                  }
    22          }
    23          if (!obj->gen_loader)
    24                  bpf_object__free_relocs(obj);
    25          return 0;
    26  }
